command:
// Independent auditor probe against the real restricted test PostgreSQL: wider races than the
// suite, duplicate storms, post-terminal and stale semantics, storage-writer checkpoint forgery,
// cross-match swaps, input/authority refusals, clock floor, create idempotency and a privacy scan.
import assert from 'node:assert/strict';
import { createHash, randomUUID } from 'node:crypto';
import { createMatchRepository } from './packages/db/dist/index.js';
import { createEngineExecutor } from './apps/match-service/dist/engine-executor.js';
import { createMatchService } from './apps/match-service/dist/service.js';
import { releases, using, cleanup } from './apps/match-service/tests/fixtures.mjs';

const rel = releases(), ids = [], owned = [];
const svc = (other = {}) => { const s = createMatchService({ repository: createMatchRepository('test'), releases: rel, now: () => 100, ...other }); owned.push(s); return s; };
const newId = tag => { const id = 'audit-' + tag + '-' + randomUUID().slice(0, 8); ids.push(id); return id; };
const C = (matchId, commandId, expectedVersion, move = 'concede', input = {}) => ({ matchId, commandId, expectedVersion, move, input });
const code = c => e => e?.code === c;
const digestOf = a => createHash('sha256').update('private-match-checkpoint-v1\0').update(a).digest('hex');
const canonical = v => { const o = x => Array.isArray(x) ? x.map(o) : x && typeof x === 'object' ? Object.fromEntries(Object.entries(x).sort(([a], [b]) => a < b ? -1 : a > b ? 1 : 0).map(([k, y]) => [k, o(y)])) : x; return JSON.stringify(o(x0(v))); };
const x0 = v => JSON.parse(JSON.stringify(v));
async function row(id) {
  return using('match', async c => {
    const n = {};
    for (const t of ['command_receipts', 'journal', 'outbox']) n[t] = (await c.query('SELECT count(*)::int AS n FROM match.' + t + ' WHERE match_id=$1', [id])).rows[0].n;
    n.completed = (await c.query("SELECT count(*)::int AS n FROM match.outbox WHERE match_id=$1 AND kind='match_completed'", [id])).rows[0].n;
    const m = (await c.query('SELECT state_version,last_timestamp,checkpoint,checkpoint_digest,ended,winner FROM match.matches WHERE match_id=$1', [id])).rows[0];
    return { ...n, version: Number(m.state_version), lastTimestamp: Number(m.last_timestamp), checkpoint: m.checkpoint, digest: m.checkpoint_digest, ended: m.ended, winner: m.winner };
  });
}
async function openMatch(s, id) {
  const created = await s.create({ matchId: id, players: ['p1', 'p2'] });
  assert.deepEqual(Object.keys(created).sort(), ['matchId', 'releaseId', 'stateVersion']);
  const chooser = JSON.parse((await row(id)).checkpoint).transcript.final.status.choosingFirstPlayer;
  let v = 0;
  for (const [a, mv, inp] of [[chooser, 'chooseWhoGoesFirst', { playerId: 'p1' }], ['p1', 'alterHand', { cardsToMulligan: [] }], ['p2', 'alterHand', { cardsToMulligan: [] }]]) {
    const r = await s.submit(a, C(id, 'open-' + a + '-' + mv, v, mv, inp));
    assert.equal(r.receipt.outcome, 'accepted'); v = r.receipt.stateVersion;
  }
  return v;
}
const RECEIPT_KEYS = ['actorId', 'commandId', 'intentHash', 'matchId', 'outcome', 'reason', 'releaseId', 'stateVersion'];
const summary = {};
const execs = [];
try {
  const base = svc();
  // 1. Six independent services/pools/executors compute concurrent same-version concessions
  //    (a terminal race across both players); a barrier holds every candidate until all exist.
  const A = newId('race'), vA = await openMatch(base, A), N = 6;
  let arrived = 0, release; const barrier = new Promise(r => { release = r; }); const safety = setTimeout(() => release(), 30000);
  const gate = e => ({ execute: async job => { const r = await e.execute(job); if (job.kind === 'transition') { if (++arrived === N) release(); await barrier; } return r; }, close: () => e.close() });
  const racers = Array.from({ length: N }, () => { const e = createEngineExecutor({ concurrency: 1 }); execs.push(e); return svc({ executor: gate(e) }); });
  const raced = await Promise.all(racers.map((s, i) => s.submit(i % 2 ? 'p2' : 'p1', C(A, 'race-' + i, vA))));
  clearTimeout(safety);
  assert.equal(arrived, N, 'every racer computed a candidate before any commit');
  const won = raced.filter(r => r.receipt.outcome === 'accepted');
  assert.equal(won.length, 1); assert.equal(raced.filter(r => r.receipt.outcome === 'stale' && r.receipt.reason === 'stale_state').length, N - 1);
  for (const r of raced) { assert.deepEqual(Object.keys(r.receipt).sort(), RECEIPT_KEYS); assert.equal(r.duplicate, false); }
  let sA = await row(A);
  assert.equal(sA.version, vA + 1); assert.equal(sA.ended, true); assert.equal(sA.winner, won[0].receipt.actorId === 'p1' ? 'p2' : 'p1');
  assert.deepEqual([sA.journal, sA.outbox, sA.completed, sA.command_receipts], [vA + 1, vA + 1, 1, vA + N]);
  // Stale losers keep their stale receipt on identical retry; changed content is an ID conflict.
  const loser = raced.findIndex(r => r.receipt.outcome === 'stale');
  const again = await base.submit(loser % 2 ? 'p2' : 'p1', C(A, 'race-' + loser, vA));
  assert.equal(again.duplicate, true); assert.deepEqual(again.receipt, raced[loser].receipt);
  await assert.rejects(base.submit(loser % 2 ? 'p2' : 'p1', C(A, 'race-' + loser, vA + 1)), code('ID_CONFLICT'));
  // Post-terminal: a fresh command at the current version is a durable invalid-intent rejection.
  const late = await base.submit('p1', C(A, 'after-end', vA + 1, 'passTurn'));
  assert.deepEqual([late.receipt.outcome, late.receipt.reason, late.receipt.stateVersion], ['rejected', 'invalid_intent', vA + 1]);
  const sA2 = await row(A); assert.equal(sA2.digest, sA.digest); assert.equal(sA2.completed, 1); assert.equal(sA2.journal, vA + 1);
  summary.terminalRace = { contenders: N, accepted: 1, stale: N - 1, terminalEvents: 1 };

  // 2. Duplicate storm: six services submit the identical command concurrently (no barrier).
  const B = newId('dup'), vB = await openMatch(base, B);
  const storm = Array.from({ length: 6 }, () => svc());
  const dup = await Promise.all(storm.map(s => s.submit('p1', C(B, 'dup', vB, 'passTurn'))));
  assert.equal(dup.filter(r => !r.duplicate).length, 1, 'exactly one first commit');
  for (const r of dup) assert.deepEqual(r.receipt, dup[0].receipt);
  assert.equal(dup[0].receipt.outcome, 'accepted');
  const sB = await row(B); assert.deepEqual([sB.version, sB.journal, sB.outbox, sB.command_receipts], [vB + 1, vB + 1, vB + 1, vB + 1]);
  summary.duplicateStorm = { submitters: 6, firstCommits: 1, identicalReceipts: 6 };

  // 3. Every non-allowlisted registry move plus prototype names, from both players, through the
  //    service: durable 'forbidden' receipts, no state/journal/outbox change.
  const refused = ['manualMoveCard', 'manualExertCard', 'manualReadyCard', 'manualDryCard', 'manualSetDamage', 'manualSetLore', 'manualSetInkDrops', 'manualShuffleDeck', 'manualPassTurn', 'forfeitGame', 'sing', 'singTogether', 'toString', '__proto__'];
  for (const actor of ['p1', 'p2']) for (const move of refused) {
    const r = await base.submit(actor, C(B, 'f-' + actor + '-' + move.replace(/_/g, 'u'), vB + 1, move, { amount: 20, playerId: actor }));
    assert.deepEqual([r.receipt.outcome, r.receipt.reason, r.receipt.stateVersion], ['rejected', 'forbidden', vB + 1], move);
  }
  const sB2 = await row(B); assert.equal(sB2.digest, sB.digest); assert.deepEqual([sB2.version, sB2.journal, sB2.outbox, sB2.ended], [vB + 1, vB + 1, vB + 1, false]);
  summary.forbiddenThroughService = refused.length * 2;

  // 4. Authority and input refusals produce no receipt.
  const before4 = await row(B);
  await assert.rejects(base.submit('p3', C(B, 'outsider', vB + 1, 'passTurn')), code('FORBIDDEN'));
  await assert.rejects(base.submit('p1', { ...C(B, 'forged', vB + 1, 'passTurn'), actor: 'p2' }), code('INVALID_REQUEST'));
  await assert.rejects(base.submit('p1', C(B, 'strver', String(vB + 1), 'passTurn')), code('INVALID_REQUEST'));
  await assert.rejects(base.submit('p1', C(B, 'fn', vB + 1, 'passTurn', { f: () => 1 })), code('INVALID_REQUEST'));
  await assert.rejects(base.submit('p1', C(B, 'bad id!', vB + 1, 'passTurn')), code('INVALID_REQUEST'));
  await assert.rejects(base.submit('p1 ', C(B, 'actorws', vB + 1, 'passTurn')), code('INVALID_REQUEST'));
  await assert.rejects(base.submit('p1', C('no-such-match', 'ghost', 0, 'passTurn')), code('FORBIDDEN'));
  let invoked = 0; const trap = C(B, 'trap', vB + 1, 'passTurn'); Object.defineProperty(trap, 'move', { enumerable: true, get() { invoked++; return 'passTurn'; } });
  await assert.rejects(base.submit('p2', trap), code('INVALID_REQUEST')); assert.equal(invoked, 0);
  const after4 = await row(B); assert.deepEqual(after4, before4);
  const outsiderRows = await using('match', async c => (await c.query("SELECT count(*)::int AS n FROM match.command_receipts WHERE match_id=$1 AND actor_id='p3'", [B])).rows[0].n);
  assert.equal(outsiderRows, 0);
  summary.authorityRefusals = 8;

  // 5. Storage-writer forgery: re-digested transcripts with an injected debug command or an altered
  //    recorded result, and a valid checkpoint swapped in from another match, fail closed.
  const good = await row(B), t = JSON.parse(good.checkpoint), last = t.transcript.commands.at(-1);
  const forgeries = [
    x => x.transcript.commands.push({ ...structuredClone(last), command: { ...last.command, commandId: 'inj', move: 'manualSetLore', input: { amount: 20, playerId: 'p2' }, expectedRevision: last.command.expectedRevision + 1 } }),
    x => { x.transcript.commands.at(-1).result = { accepted: false, code: 'X' }; },
    x => { x.transcript.final.status.ended = true; x.transcript.final.status.winner = 'p2'; },
  ];
  for (const f of forgeries) {
    const y = structuredClone(t); f(y); const a = canonical(y);
    await using('match', c => c.query('UPDATE match.matches SET checkpoint=$2,checkpoint_digest=$3 WHERE match_id=$1', [B, a, digestOf(a)]));
    await assert.rejects(base.submit('p2', C(B, 'after-forgery-' + forgeries.indexOf(f), vB + 1, 'passTurn')), code('UNAVAILABLE'));
  }
  const swap = await row(A);
  await using('match', c => c.query('UPDATE match.matches SET checkpoint=$2,checkpoint_digest=$3 WHERE match_id=$1', [B, swap.checkpoint, swap.digest]));
  await assert.rejects(base.submit('p2', C(B, 'after-swap', vB + 1, 'passTurn')), code('UNAVAILABLE'));
  await using('match', c => c.query('UPDATE match.matches SET checkpoint=$2,checkpoint_digest=$3 WHERE match_id=$1', [B, good.checkpoint, good.digest]));
  const forgedReceipts = await using('match', async c => (await c.query("SELECT count(*)::int AS n FROM match.command_receipts WHERE match_id=$1 AND command_id LIKE 'after-%'", [B])).rows[0].n);
  assert.equal(forgedReceipts, 0);
  const recovered = await base.submit('p2', C(B, 'recovered', vB + 1, 'passTurn'));
  assert.equal(recovered.receipt.outcome, 'accepted');
  summary.storageForgeriesFailClosed = forgeries.length + 1;

  // 6. Fresh-instance lost acknowledgement, cross-match command-id isolation, clock floor, create idempotency.
  const D = newId('iso'), vD = await openMatch(base, D);
  const slow = svc({ now: () => 1 });
  const first = await slow.submit('p1', C(D, 'dup', vD, 'passTurn'));
  assert.equal(first.duplicate, false, 'same command id on another match is independent');
  assert.equal((await row(D)).lastTimestamp, 100, 'server time floored at last committed capture');
  await slow.close();
  const fresh = svc(); const retry = await fresh.submit('p1', C(D, 'dup', vD, 'passTurn'));
  assert.equal(retry.duplicate, true); assert.deepEqual(retry.receipt, first.receipt);
  await assert.rejects(base.create({ matchId: D, players: ['p1', 'p9'] }), code('ID_CONFLICT'));
  await assert.rejects(base.create({ matchId: D, players: ['p2', 'p1'] }), code('ID_CONFLICT'));
  const reopened = await base.create({ matchId: D, players: ['p1', 'p2'] });
  assert.equal(reopened.stateVersion, vD + 1, 'existing match returned, not reset');
  const future = await base.submit('p2', C(D, 'future', vD + 9, 'passTurn'));
  assert.deepEqual([future.receipt.outcome, future.receipt.reason], ['stale', 'stale_state']);
  summary.lostAckClockCreate = true;

  // 7. Privacy scan of every durable non-checkpoint row for these matches.
  let scanned = 0;
  for (const id of ids) {
    const r = await row(id), seed = JSON.parse(r.checkpoint).transcript.seed;
    assert.match(seed, /^[a-f0-9]{64}$/);
    await using('match', async c => {
      for (const table of ['command_receipts', 'journal', 'outbox']) {
        for (const x of (await c.query('SELECT row_to_json(t)::text AS j FROM match.' + table + ' t WHERE match_id=$1', [id])).rows) {
          for (const secret of [seed, '"transcript"', 'stateHash', 'randomOutcomes', 'seedCommitment', r.checkpoint.slice(0, 200)]) assert.equal(x.j.includes(secret), false, table + ' leaks ' + secret.slice(0, 16));
          scanned++;
        }
      }
      const cols = (await c.query("SELECT column_name FROM information_schema.columns WHERE table_schema='match' AND table_name='outbox' ORDER BY ordinal_position")).rows.map(x => x.column_name);
      assert.deepEqual(cols, ['event_id', 'match_id', 'state_version', 'kind', 'created_at']);
    });
  }
  summary.privacyRowsScanned = scanned;
} finally {
  for (const s of owned) await s.close().catch(() => {});
  for (const e of execs) await e.close().catch(() => {});
  for (const id of ids) await cleanup(id);
  const left = await using('match', async c => (await c.query("SELECT count(*)::int AS n FROM match.matches WHERE match_id LIKE 'audit-%'")).rows[0].n);
  summary.leftoverAuditMatches = left;
}
assert.equal(summary.leftoverAuditMatches, 0);
console.log(JSON.stringify(summary));
console.log('PASS auditor PLAY-01 live service probe on restricted test PostgreSQL: six-way terminal race commits once with one terminal event; six-way duplicate storm yields one commit and identical receipts; every refused move is a durable forbidden receipt without mutation; authority/input refusals write nothing; re-digested forged or swapped checkpoints fail closed; lost-ack retry, command-id isolation, clock floor and create idempotency hold; no seed or private transcript in receipts/journal/outbox; owned fixtures removed');
